Lemma stk_wr_at' : forall (m : mem) a k, stk asegs m a (a + k) -> wr_at asegs m a k.
Proof. intros m a k (H0 & H1 & H). split; [lia|]. split; [lia|]. intros j Hj. exact (proj1 (H (a + j) ltac:(lia))). Qed.

